#ifndef LRU_CACHE_H
#define LRU_CACHE_H

#include <optional>
#include <unordered_map>
#include <list>
#include <mutex>
#include <cstddef>

template <typename K, typename V>
class LRUCache {
private:
    struct Node {
        K key;
        V value;
    };

    std::size_t capacity_;
    std::list<Node> order_list_; // Front is most recently used, back is least recently used
    std::unordered_map<K, typename std::list<Node>::iterator> map_;
    mutable std::mutex mutex_;

public:
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {}

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // Move to front (most recently used)
        order_list_.splice(order_list_.begin(), order_list_, it->second);
        return it->second->value;
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            // Key exists, update value and move to front
            it->second->value = value;
            order_list_.splice(order_list_.begin(), order_list_, it->second);
        } else {
            // New key
            if (map_.size() == capacity_) {
                // Evict least recently used (back of the list)
                auto last = order_list_.back();
                map_.erase(last.key);
                order_list_.pop_back();
            }
            order_list_.push_front({key, value});
            map_[key] = order_list_.begin();
        }
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return map_.size();
    }
};

#endif // LRU_CACHE_H
