#include <cstddef>
#include <stdexcept>
#include <utility>

class Matrix {
private:
    int rows_;
    int cols_;
    double* data_;

    void validate_dims(int rows, int cols) const {
        if (rows <= 0 || cols <= 0) {
            throw std::invalid_argument("Matrix dimensions must be positive");
        }
    }

    void allocate(int rows, int cols) {
        validate_dims(rows, cols);
        rows_ = rows;
        cols_ = cols;
        data_ = new double[rows * cols]();
    }

    void deallocate() {
        delete[] data_;
    }

    void copy_from(const Matrix& other) {
        rows_ = other.rows_;
        cols_ = other.cols_;
        data_ = new double[rows_ * cols_];
        for (int i = 0; i < rows_ * cols_; ++i) {
            data_[i] = other.data_[i];
        }
    }

    void move_from(Matrix&& other) noexcept {
        rows_ = other.rows_;
        cols_ = other.cols_;
        data_ = other.data_;
        other.rows_ = 0;
        other.cols_ = 0;
        other.data_ = nullptr;
    }

public:
    Matrix(int rows, int cols) {
        allocate(rows, cols);
    }

    ~Matrix() {
        deallocate();
    }

    Matrix(const Matrix& other) {
        copy_from(other);
    }

    Matrix(Matrix&& other) noexcept {
        move_from(std::move(other));
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            deallocate();
            copy_from(other);
        }
        return *this;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            deallocate();
            move_from(std::move(other));
        }
        return *this;
    }

    double& at(int r, int c) {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Matrix index out of range");
        }
        return data_[r * cols_ + c];
    }

    double at(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Matrix index out of range");
        }
        return data_[r * cols_ + c];
    }

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            throw std::invalid_argument("Matrix dimensions must match for addition");
        }
        Matrix result(rows_, cols_);
        for (int i = 0; i < rows_ * cols_; ++i) {
            result.data_[i] = data_[i] + o.data_[i];
        }
        return result;
    }

    Matrix operator*(const Matrix& o) const {
        if (cols_ != o.rows_) {
            throw std::invalid_argument("Matrix dimensions mismatch for multiplication");
        }
        Matrix result(rows_, o.cols_);
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < o.cols_; ++j) {
                double sum = 0.0;
                for (int k = 0; k < cols_; ++k) {
                    sum += data_[i * cols_ + k] * o.data_[k * o.cols_ + j];
                }
                result.data_[i * o.cols_ + j] = sum;
            }
        }
        return result;
    }

    bool operator==(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            return false;
        }
        for (int i = 0; i < rows_ * cols_; ++i) {
            if (data_[i] != o.data_[i]) {
                return false;
            }
        }
        return true;
    }
};
